// 1. Install prettier locally: npm install prettier
// 2. Create a file named `unsafeCoerce.mts` with the following content:
export const unsafeCoerce = <T,>(u: unknown): T => u as T

// 3. Create a .prettierrc.js in the same folder:
module.exports = {
    trailingComma: 'all',
    tabWidth: 4,
    semi: false,
    singleQuote: true,
};

// 4. Run Prettier via CLI:
//    npx prettier --write unsafeCoerce.mts
// 5. Observe that the file is reformatted to:
//    export const unsafeCoerce = <T>(u: unknown): T => u as T
// 6. TypeScript will now report TS7060 on the `<T>` generic in .mts files.

// Alternatively, reproduce via the Prettier API:
const prettier = require('prettier')
const code = `export const unsafeCoerce = <T,>(u: unknown): T => u as T`
const options = {
  parser: 'typescript',
  filepath: 'unsafeCoerce.mts',
  trailingComma: 'all',
  tabWidth: 4,
  semi: false,
  singleQuote: true,
}

const formatted = prettier.format(code, options)
console.log(formatted)
